// Shared labels and a bounded, readable review of personnel changes.
export const personnelFields={employee_code:'เลขที่ตำแหน่ง',full_name:'ชื่อ–นามสกุล',school_id:'สถานศึกษา',user_id:'บัญชีผู้ใช้งาน',position:'ตำแหน่ง',department:'ฝ่าย',academic_rank:'วิทยฐานะ',highest_education:'วุฒิการศึกษาสูงสุด',education_majors:'สาขาวิชา',birth_date:'วันเกิด',start_date:'วันเริ่มงาน',retirement_override:'วันเกษียณตามคำสั่ง',email:'อีเมล',phone:'โทรศัพท์',address:'ที่อยู่',avatar_data:'รูปโปรไฟล์',status:'สถานะเดิมในทะเบียน',deleted_at:'วันที่ลบ',deleted_by:'ผู้ลบ',delete_reason:'เหตุผลการลบ'};
const normalized=value=>Array.isArray(value)?JSON.stringify(value):value==null?'':String(value);
export function personnelDiff(before={},patch={}){return Object.entries(personnelFields).filter(([key])=>Object.hasOwn(patch,key)&&normalized(before[key])!==normalized(patch[key])).map(([key,label])=>({key,label,before:before[key]??'',after:patch[key]??''}));}
export function historySnapshot(person){const row=Object.fromEntries(Object.keys(personnelFields).filter(k=>Object.hasOwn(person,k)).map(k=>[k,structuredClone(person[k])]));if(Object.hasOwn(row,'avatar_data')){let hash=5381;for(const char of row.avatar_data||'')hash=((hash*33)^char.charCodeAt(0))>>>0;row.avatar_data=row.avatar_data?'รูปโปรไฟล์ #'+hash.toString(16):'';}return row;}
export function requireRevision(value){if(!Number.isSafeInteger(value)||value<1)throw Error('ข้อมูลรุ่นเก่า กรุณาโหลดรายชื่อใหม่ก่อนดำเนินการ');return value;}
export function validateChangeReason(value){const reason=String(value||'').trim();if(reason.length<5||reason.length>1000)throw Error('กรุณาระบุเหตุผล 5–1,000 ตัวอักษร');return reason;}
